-- Corsi: percorsi a lezioni in ordine per ogni strumento, che usano esercizi, brani e attrezzi del sito.
-- explanation, practice e checklist sono elenchi separati da "|". tool: accordatore | accordi-chitarra | scale | accordi-piano | orecchio.
-- Generato da uno script a partire dal testo delle lezioni: modificare qui e rieseguire, oppure aggiornare le righe a mano.
CREATE TABLE IF NOT EXISTS public.learning_paths (
  id text PRIMARY KEY,
  instrument_id text NOT NULL REFERENCES public.instruments(id),
  title text NOT NULL,
  subtitle text NOT NULL,
  description text NOT NULL,
  level int NOT NULL DEFAULT 1,
  sort int NOT NULL DEFAULT 0
);
CREATE TABLE IF NOT EXISTS public.lessons (
  id text PRIMARY KEY,
  path_id text NOT NULL REFERENCES public.learning_paths(id) ON DELETE CASCADE,
  sort int NOT NULL,
  title text NOT NULL,
  goal text NOT NULL,
  explanation text NOT NULL,
  practice text NOT NULL,
  checklist text NOT NULL,
  minutes int NOT NULL DEFAULT 15,
  bpm int,
  notation text,
  exercise_id text REFERENCES public.exercises(id),
  song_id text REFERENCES public.songs(id),
  tool text CHECK (tool IN ('accordatore', 'accordi-chitarra', 'scale', 'accordi-piano', 'orecchio')),
  tool_note int CHECK (tool_note BETWEEN 0 AND 11),
  tool_kind text
);
CREATE INDEX IF NOT EXISTS lessons_path_sort_idx ON public.lessons (path_id, sort);

GRANT SELECT ON public.learning_paths, public.lessons TO anon, authenticated;
GRANT ALL ON public.learning_paths, public.lessons TO service_role;
ALTER TABLE public.learning_paths ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.lessons ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "public read" ON public.learning_paths;
CREATE POLICY "public read" ON public.learning_paths FOR SELECT USING (true);
DROP POLICY IF EXISTS "public read" ON public.lessons;
CREATE POLICY "public read" ON public.lessons FOR SELECT USING (true);

INSERT INTO public.learning_paths (id, instrument_id, title, subtitle, description, level, sort) VALUES
('chitarra-da-zero','chitarra','Chitarra da zero','Dal primo accordo al primo brano','Otto lezioni per chi non ha mai suonato: accordare, i primi accordi, il ritmo, i power chord, la pentatonica e un brano completo.',1,1),
('chitarra-rock','chitarra','Chitarra rock: riff e assoli','Tecnica per suonare i brani rock','Pennata alternata, riff a note singole, legato, bending e improvvisazione in pentatonica, fino a un classico dell''hard rock.',2,2),
('basso-da-zero','basso','Basso da zero','Il groove, una nota alla volta','Sei lezioni per tenere il tempo con la band: postura, dita alternate, fondamentali, note sul manico, ottave e il primo brano.',1,1),
('pianoforte-da-zero','pianoforte','Pianoforte da zero','Dalla tastiera al primo brano a due mani','Sei lezioni per orientarsi sulla tastiera, suonare la prima scala, gli accordi principali e accompagnare un brano con due mani.',1,1),
('batteria-da-zero','batteria','Batteria da zero','Dal primo colpo al primo groove','Sei lezioni per conoscere il set, controllare le bacchette, suonare il groove rock e il primo fill, con due brani veri.',1,1)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.lessons (id, path_id, sort, title, goal, explanation, practice, checklist, minutes, bpm, notation, exercise_id, song_id, tool, tool_note, tool_kind) VALUES
('cz-1','chitarra-da-zero',1,'Tenere la chitarra e accordarla','Avere la chitarra accordata e una posizione comoda per suonare a lungo.','Siediti con la schiena dritta e appoggia la chitarra sulla gamba destra (sinistra se sei mancino): il manico punta un po'' verso l''alto e il braccio destro cade naturale sul corpo.|Le corde si contano dalla più sottile alla più grossa: la 1ª è il Mi cantino, la 6ª il Mi grave. Dal grave all''acuto si chiamano Mi, La, Re, Sol, Si, Mi (E A D G B E).|Una chitarra scordata fa sembrare sbagliato anche quello che suoni bene: accordala ogni volta che inizi.','Apri l''accordatore e accorda le sei corde, dalla 6ª alla 1ª.|Tieni il plettro tra pollice e lato dell''indice, con la punta che sporge di pochi millimetri.|Suona ogni corda a vuoto 4 volte a tempo con il metronomo, dicendo ad alta voce il suo nome.','So i nomi delle sei corde|So accordare la chitarra da solo|Tengo il plettro senza stringerlo troppo',10,60,'Corda:  6   5   4   3   2   1
Nota:   Mi  La  Re  Sol Si  Mi
        E   A   D   G   B   E',NULL,NULL,'accordatore',NULL,NULL),
('cz-2','chitarra-da-zero',2,'Le prime note: un dito per tasto','Premere le note in modo pulito con tutte e quattro le dita della mano sinistra.','Premi la corda subito dietro la barretta metallica del tasto, con la punta del dito: serve meno forza e la nota suona più pulita.|Usa un dito per tasto: indice al 1°, medio al 2°, anulare al 3°, mignolo al 4°. Il pollice resta dietro il manico, più o meno all''altezza del medio.|Lo spider walk sembra noioso, ma è l''esercizio che rende indipendenti le dita: bastano pochi minuti al giorno.','Suona 1-2-3-4 sulla 6ª corda, poi passa alla 5ª e così via fino alla 1ª.|Torna indietro dalla 1ª alla 6ª.|Quando ogni nota suona pulita, alza il metronomo di 5 BPM.','Ogni nota suona senza ronzii|Il pollice resta dietro il manico|Arrivo a 80 BPM senza fermarmi',10,60,NULL,'g-spider',NULL,NULL,NULL,NULL),
('cz-3','chitarra-da-zero',3,'I primi accordi: Mi minore e La minore','Suonare Em e Am facendo suonare tutte le corde giuste.','Un accordo sono tre o più note suonate insieme. Mi minore (Em) è il più facile: due dita al 2° tasto di 5ª e 4ª corda, e tutte le corde a vuoto.|La minore (Am) si suona dalla 5ª corda: la 6ª non va suonata. Le dita formano un piccolo triangolo tra 2° e 1° tasto.|Se una corda non suona, quasi sempre un dito la sta toccando: arcua di più le dita.','Forma Em e suona le corde una alla volta: devono suonare tutte e sei.|Fai lo stesso con Am, partendo dalla 5ª corda.|Alterna 4 pennate di Em e 4 di Am, senza fermarti nel cambio.','Em suona pulito su tutte le corde|Am suona pulito senza la 6ª corda|Cambio tra i due senza fermare il tempo',15,60,'        Em       Am
6ª Mi   0        x
5ª La   2        0
4ª Re   2        2
3ª Sol  0        2
2ª Si   0        1
1ª Mi   0        0',NULL,NULL,'accordi-chitarra',4,'min'),
('cz-4','chitarra-da-zero',4,'Il ritmo: pennate in giù e in su','Tenere un ritmo regolare con il braccio che si muove come un pendolo.','Conta 1 e 2 e 3 e 4 e: sui numeri la pennata va in giù, sulle "e" va in su.|Il segreto è che il braccio non si ferma mai: va su e giù anche quando non tocchi le corde. Così il tempo resta sempre preciso.|Il ritmo qui sotto (giù, giù-su, su-giù-su) è quello di moltissime canzoni pop e rock.','Con le corde stoppate dalla mano sinistra, fai solo il movimento del ritmo a 70 BPM.|Ora suonalo su Em, poi su Am.|Alterna una battuta di Em e una di Am con questo ritmo.','Il braccio non si ferma mai|Riesco a contare ad alta voce mentre suono|Cambio accordo senza perdere il ritmo',15,70,'Conta:  1   e   2   e   3   e   4   e
Penna:  ↓       ↓   ↑       ↑   ↓   ↑',NULL,NULL,NULL,NULL,NULL),
('cz-5','chitarra-da-zero',5,'Accordi maggiori: Do, Sol e Re','Conoscere i tre accordi maggiori più usati e cambiarli a tempo.','Con Em, Am, C, G e D suoni già centinaia di canzoni.|Cerca le dita in comune: tra C e Am, per esempio, indice e medio restano dove sono e si sposta solo l''anulare.|Il cambio di un minuto è il modo migliore per migliorare: conti quanti cambi riesci a fare in 60 secondi e provi a battere il tuo record.','Impara le tre forme controllando ogni corda una alla volta.|Fai un minuto di cambi C ↔ G, poi G ↔ D, e scrivi quanti ne hai fatti.|Suona il giro G - D - Em - C con 4 pennate per accordo.','C, G e D suonano puliti|Faccio almeno 30 cambi al minuto|Suono il giro G - D - Em - C a tempo',20,70,'        C        G        D
6ª Mi   x        3        x
5ª La   3        2        x
4ª Re   2        0        0
3ª Sol  0        0        2
2ª Si   1        0        3
1ª Mi   0        3        2','g-chords',NULL,'accordi-chitarra',7,'maj'),
('cz-6','chitarra-da-zero',6,'Power chord e palm muting','Suonare i power chord, il suono base del rock, anche smorzati.','Il power chord ha solo due note: la fondamentale e la quinta. Non è né maggiore né minore, per questo suona benissimo con la distorsione.|La forma è sempre la stessa: indice sulla corda grave, anulare due tasti più su sulla corda sotto. Spostandola lungo il manico cambi accordo.|Il palm muting si fa appoggiando il lato della mano destra sulle corde, proprio vicino al ponte: il suono diventa corto e potente.','Suona G5, A5 e C5 lasciando suonare le note.|Ora suonali in palm muting con pennate in giù in ottavi.|Ascolta il brano e prova a riconoscere dove si usano i power chord.','La forma resta uguale mentre la sposto|Suono solo le due corde giuste|Il palm muting suona corto ma si sente la nota',20,80,'        G5       A5       C5
4ª Re   -        -        5
5ª La   5        7        3
6ª Mi   3        5        -','g-palmmute','smoke-on-the-water','accordi-chitarra',4,'5'),
('cz-7','chitarra-da-zero',7,'La pentatonica minore','Suonare la scala degli assoli rock e blues a memoria.','La pentatonica minore ha cinque note ed è la scala più usata negli assoli. Qui la suoni in La, partendo dal 5° tasto della 6ª corda.|La forma (il "box 1") si ripete uguale in ogni tonalità: basta spostarla. Se parti dal 3° tasto, per esempio, sei in Sol.|Usa indice per il 5° tasto e anulare o mignolo per il 7° e l''8°.','Sali dalla 6ª alla 1ª corda e scendi, due note per corda.|Usa pennata alternata: giù, su, giù, su.|Suona la scala con il metronomo e poi prova a improvvisare liberamente usando solo queste note.','Suono la scala a memoria in salita e discesa|Uso la pennata alternata|So spostarla in un''altra tonalità',15,70,'e|---------------------5--8--|
B|----------------5--8-------|
G|-----------5--7------------|
D|------5--7-----------------|
A|-5--7----------------------|  (prima: 6ª corda 5-8)
E|-5--8----------------------|','g-pentatonic',NULL,'scale',9,'penta-minore'),
('cz-8','chitarra-da-zero',8,'Il tuo primo brano completo','Suonare dall''inizio alla fine un brano vero con gli accordi che conosci.','Zombie dei Cranberries gira su quattro accordi che hai già imparato: Em, C, G e D.|Non serve suonarlo subito alla velocità del disco: usa l''allenamento velocità del metronomo, che parte più lento e sale da solo.|Quando riesci a suonarlo tutto senza fermarti, hai finito il corso: complimenti!','Ripassa il giro Em - C - G - D con il ritmo della lezione 4.|Apri lo spartito originale dalla pagina del brano e segui la struttura (strofa, ritornello).|Suona il brano intero con il disco o con il metronomo.','Conosco la struttura del brano|Lo suono dall''inizio alla fine senza fermarmi|Lo suono alla velocità originale',25,NULL,NULL,NULL,'zombie',NULL,NULL,NULL),
('cr-1','chitarra-rock',1,'Pennata alternata pulita','Suonare note veloci e regolari alternando giù e su.','La pennata alternata è la base di riff e assoli veloci: una pennata in giù, la successiva in su, sempre.|Muovi il polso, non tutto il braccio, e tieni il plettro vicino alle corde: meno strada fa, più sei veloce.|La velocità arriva da sola se sei preciso. Aumenta il metronomo solo quando suoni pulito per un minuto intero.','Suona quattro note per tempo su una corda sola, a vuoto.|Passa allo spider walk con pennata alternata.|Accendi l''allenamento velocità del metronomo e fermati quando le note iniziano a sporcarsi.','Alterno sempre giù e su, anche cambiando corda|Il movimento parte dal polso|Guadagno 10 BPM rispetto all''inizio',15,80,NULL,'g-alternate',NULL,NULL,NULL,NULL),
('cr-2','chitarra-rock',2,'Riff a note singole','Suonare un riff famoso senza far suonare le corde sbagliate.','Molti riff rock sono fatti di note singole: il difficile non è premere le note, è non far suonare le altre corde.|Appoggia leggermente le dita della mano sinistra che non usi sulle altre corde, e il palmo destro su quelle gravi: così restano mute.|Seven Nation Army è il riff perfetto per cominciare: poche note, tutte sulle corde gravi.','Apri lo spartito del brano e impara il riff lentamente.|Controlla che si senta solo una corda alla volta.|Suonalo a tempo con il metronomo, poi con il disco.','Le altre corde restano mute|Suono il riff a memoria|Lo suono alla velocità originale',15,NULL,NULL,NULL,'seven-nation-army',NULL,NULL,NULL),
('cr-3','chitarra-rock',3,'Hammer-on e pull-off','Suonare più note con una sola pennata, in modo fluido.','Con l''hammer-on suoni una nota "martellando" il dito sul tasto, senza pennare. Con il pull-off tiri via il dito di lato e fai suonare la nota sotto.|Insieme si chiamano legato: rendono le frasi più morbide e veloci, e sono in quasi tutti gli assoli.','Hammer-on dal 5° al 7° tasto sulla 3ª corda: le due note devono avere lo stesso volume.|Pull-off dal 7° al 5°: tira il dito leggermente verso il basso.|Combina i due: 5-7-5 con una sola pennata.','La nota dell''hammer-on suona forte come quella pennata|Il pull-off non fa suonare le altre corde|Suono 5-7-5 in modo fluido',15,70,NULL,'g-legato',NULL,NULL,NULL,NULL),
('cr-4','chitarra-rock',4,'Bending intonato','Alzare una nota con il bending fino a quella giusta.','Il bending è la tecnica che fa "cantare" la chitarra: spingi la corda verso l''alto e la nota sale.|Il difficile è arrivare alla nota giusta. Prima suona la nota bersaglio due tasti più su, poi prova a raggiungerla con il bending e confronta.|Spingi con tre dita insieme (anulare aiutato da medio e indice) e fai ruotare il polso, come quando giri una maniglia.','Suona il 9° tasto della 3ª corda e ascolta bene la nota.|Ora suona il 7° tasto e spingi fino a raggiungere quella nota.|Alterna: nota bersaglio, bending, nota bersaglio.','Il bending arriva alla nota giusta|Uso tre dita per spingere|Riesco a tenere la nota alzata senza calare',15,60,NULL,'g-bending',NULL,NULL,NULL,NULL),
('cr-5','chitarra-rock',5,'Il primo assolo: la scala blues','Improvvisare un assolo semplice con frasi brevi.','La scala blues è la pentatonica minore con una nota in più, la "blue note": in La è il Mi bemolle, che dà quel suono un po'' sporco tipico del blues e del rock.|Un buon assolo è fatto di frasi brevi, come se parlassi: una domanda e una risposta, con pause in mezzo.|Usa le tecniche che conosci: legato, bending e vibrato sulle note lunghe.','Suona la scala blues in La e ascolta la blue note.|Inventa una frase di 3-4 note, poi una che le risponde.|Improvvisa per due minuti con il metronomo, lasciando pause tra le frasi.','Conosco la scala blues in La|Le mie frasi hanno delle pause|Uso almeno un bending nell''assolo',20,80,NULL,NULL,NULL,'scale',9,'blues'),
('cr-6','chitarra-rock',6,'Un classico dell''hard rock','Mettere insieme accordi, riff e palm muting in un brano completo.','Back in Black alterna accordi aperti e piccoli riff in pentatonica di Mi: è un ottimo riassunto di quello che hai imparato.|Il segreto del suono è il tempo preciso e le pause: le note corte e stoppate contano quanto quelle suonate.|Usa le impostazioni del suono nella pagina del brano per avvicinarti al disco.','Impara il riff principale lentamente.|Usa l''allenamento velocità per arrivare al tempo originale.|Suona tutto il brano insieme al disco.','Il riff è preciso nelle pause|Arrivo alla velocità originale|Suono il brano dall''inizio alla fine',25,NULL,NULL,NULL,'back-in-black',NULL,NULL,NULL),
('bz-1','basso-da-zero',1,'Accordare e posizione','Avere il basso accordato e una posizione comoda per entrambe le mani.','Il basso a quattro corde si accorda Mi, La, Re, Sol (E A D G), dal grave all''acuto: sono le stesse note delle quattro corde gravi della chitarra, un''ottava sotto.|Appoggia il pollice destro sul pickup o sulla corda di Mi: dà stabilità alla mano e tiene muta la corda grave.|Pizzica la corda tirandola verso di te e fai fermare il dito sulla corda di sotto: si chiama "appoggiato" e dà un suono pieno.','Accorda le quattro corde con l''accordatore.|Suona ogni corda a vuoto 4 volte con l''indice, a tempo.|Ripeti con il medio.','So accordare il basso da solo|Il pollice destro ha un punto d''appoggio|Il dito si ferma sulla corda di sotto',10,60,'Corda:  4   3   2   1
Nota:   Mi  La  Re  Sol
        E   A   D   G',NULL,NULL,'accordatore',NULL,NULL),
('bz-2','basso-da-zero',2,'Indice e medio alternati','Suonare note regolari alternando sempre le due dita.','I bassisti alternano indice e medio, come i chitarristi alternano la pennata: così si suona veloce senza stancarsi.|Le due dita devono suonare con lo stesso volume: registrati e ascolta se una nota è più forte dell''altra.','Suona ottavi sulla corda di La alternando indice e medio.|Cambia corda senza interrompere l''alternanza.|Accendi il metronomo e tieni 2 minuti senza fermarti.','Non suono mai due volte con lo stesso dito|Le note hanno tutte lo stesso volume|Tengo il tempo per 2 minuti',10,70,NULL,'b-fingers',NULL,NULL,NULL,NULL),
('bz-3','basso-da-zero',3,'Le fondamentali: il lavoro del bassista','Accompagnare un giro di accordi suonando la nota principale di ogni accordo.','La fondamentale è la nota che dà il nome all''accordo: di La minore è il La, di Do è il Do. Suonarla a tempo è il primo lavoro del bassista.|Insieme alla batteria tieni in piedi il brano: un bassista che suona poche note ma a tempo vale più di uno che ne suona tante.','Suona otto note di La (5ª corda a vuoto), poi otto di Re (4ª a vuoto).|Aggiungi Mi (corda di Mi a vuoto) e torna al La.|Ripeti il giro La - Re - Mi - La a 80 BPM.','So cos''è una fondamentale|Cambio nota senza perdere il tempo|Il suono è regolare a 80 BPM',15,80,NULL,'b-root',NULL,NULL,NULL,NULL),
('bz-4','basso-da-zero',4,'Le note sul manico','Trovare le note naturali sulle corde di Mi e di La.','Per suonare le fondamentali di qualsiasi accordo ti serve sapere dove sono le note. Le corde di Mi e di La bastano per quasi tutto.|Tra Mi e Fa e tra Si e Do c''è solo un tasto; tra tutte le altre note naturali ce ne sono due.|Al 12° tasto le note ricominciano uguali, un''ottava sopra.','Suona e di'' ad alta voce le note della corda di Mi, dal tasto 0 al 12.|Fai lo stesso sulla corda di La.|Chiedi a qualcuno (o pesca a caso) una nota e trovala sulle due corde.','Trovo ogni nota naturale sulla corda di Mi|Trovo ogni nota naturale sulla corda di La|So dove sono Mi-Fa e Si-Do',15,NULL,'Tasto:     0   1   3   5   7   8   10  12
Corda Mi:  Mi  Fa  Sol La  Si  Do  Re  Mi

Tasto:     0   2   3   5   7   8   10  12
Corda La:  La  Si  Do  Re  Mi  Fa  Sol La',NULL,NULL,NULL,NULL,NULL),
('bz-5','basso-da-zero',5,'Le ottave','Suonare le ottave, il movimento che fa ballare una linea di basso.','L''ottava è la stessa nota, più acuta. Sul basso la trovi sempre due tasti più su e due corde più in alto.|Alternare fondamentale e ottava è la base della disco e del funk: con l''indice sulla nota grave e il mignolo (o l''anulare) sull''ottava.|Smorza la nota grave quando suoni quella acuta, alzando leggermente l''indice: il suono resta pulito.','Suona La al 5° tasto della corda di Mi e La al 7° della corda di Re.|Alterna le due note in ottavi.|Sposta la forma: Sol (3° tasto) e Do (8° tasto).','Trovo l''ottava di qualsiasi nota|Le note non suonano insieme|Sposto la forma sul manico a tempo',15,90,NULL,'b-octaves',NULL,NULL,NULL,NULL),
('bz-6','basso-da-zero',6,'Il primo brano','Suonare una delle linee di basso più famose di sempre.','Another One Bites the Dust è costruita quasi tutta su poche note della corda di La e di Mi: perfetta per mettere insieme quello che hai imparato.|Il segreto della linea sono le pause: contale bene, sono parte del groove.|Usa l''allenamento velocità del metronomo per arrivare al tempo del disco.','Apri lo spartito dalla pagina del brano e impara la linea principale.|Suonala lentamente contando le pause ad alta voce.|Suona tutto il brano con il disco.','Conosco la linea a memoria|Le pause sono precise|Suono tutto il brano con il disco',25,NULL,NULL,NULL,'another-one',NULL,NULL,NULL),
('pz-1','pianoforte-da-zero',1,'Orientarsi sulla tastiera','Trovare subito ogni nota bianca sulla tastiera.','I tasti neri sono in gruppi di due e di tre: sono i tuoi punti di riferimento. Il Do è il tasto bianco subito a sinistra di ogni gruppo di due neri.|Dal Do, i tasti bianchi verso destra sono Do, Re, Mi, Fa, Sol, La, Si, poi ricomincia un altro Do.|Le dita si numerano uguali nelle due mani: 1 il pollice, 2 l''indice, 3 il medio, 4 l''anulare, 5 il mignolo.','Trova e suona tutti i Do della tastiera.|Ora tutti i Fa (a sinistra del gruppo di tre neri).|Suona Do-Re-Mi-Fa-Sol con le dita 1-2-3-4-5 della mano destra.','Trovo il Do senza contare|Conosco i nomi dei tasti bianchi|So la numerazione delle dita',10,NULL,'Gruppo di 2 neri:   ■ ■           Gruppo di 3 neri:  ■ ■ ■
Tasti bianchi:     Do Re Mi                         Fa Sol La Si',NULL,NULL,'scale',0,'maggiore'),
('pz-2','pianoforte-da-zero',2,'La scala di Do maggiore','Suonare la scala di Do con la mano destra e la diteggiatura giusta.','La scala di Do maggiore usa solo tasti bianchi: è la prima che si impara.|Con cinque dita e otto note serve un trucco: dopo il Mi il pollice passa sotto la mano e suona il Fa. La diteggiatura è 1-2-3-1-2-3-4-5.|Tieni il polso morbido e le dita arrotondate, come se tenessi una pallina.','Suona la scala salendo con 1-2-3-1-2-3-4-5.|Scendi con 5-4-3-2-1-3-2-1: questa volta è il medio a passare sopra il pollice.|Suonala a tempo, una nota per battito.','Il passaggio del pollice è fluido|Uso sempre la stessa diteggiatura|Suono la scala a tempo',15,60,NULL,'p-c-scale',NULL,NULL,NULL,NULL),
('pz-3','pianoforte-da-zero',3,'I primi accordi: Do, Fa e Sol','Suonare i tre accordi più importanti in Do maggiore.','Un accordo di tre note (triade) si forma prendendo una nota sì e una no: Do-Mi-Sol è l''accordo di Do maggiore.|Con la mano destra usa le dita 1-3-5. La stessa forma, spostata, ti dà Fa (Fa-La-Do) e Sol (Sol-Si-Re).|Con questi tre accordi si suonano tantissime canzoni.','Suona Do, Fa e Sol, quattro volte ciascuno.|Ascolta se le tre note suonano insieme e con lo stesso volume.|Suona il giro Do - Fa - Sol - Do a tempo.','Le tre note partono insieme|Trovo Do, Fa e Sol senza guardare l''elenco|Suono il giro a tempo',15,60,'Do maggiore:   Do - Mi - Sol
Fa maggiore:   Fa - La - Do
Sol maggiore:  Sol - Si - Re
La minore:     La - Do - Mi',NULL,NULL,'accordi-piano',0,'maj'),
('pz-4','pianoforte-da-zero',4,'Le due mani insieme','Accompagnare un giro di accordi con due mani.','La mano sinistra suona la fondamentale, cioè la nota che dà il nome all''accordo, un''ottava più in basso. La destra suona l''accordo.|Il giro Do - Sol - La minore - Fa è forse il più usato della musica pop.|All''inizio suonate le mani nello stesso momento; quando va bene, prova a suonare la sinistra sul primo battito e la destra sugli altri tre.','Mano sinistra da sola: Do, Sol, La, Fa, una nota per battuta.|Mano destra da sola: gli accordi Do, Sol, Am, Fa.|Ora insieme, quattro battiti per accordo.','La sinistra trova le fondamentali senza guardare|Le mani partono insieme|Suono il giro senza fermarmi',20,60,NULL,NULL,NULL,NULL,NULL,NULL),
('pz-5','pianoforte-da-zero',5,'I rivolti: cambiare accordo muovendo poco','Passare da un accordo all''altro con il minimo movimento.','Le note di un accordo si possono suonare in ordine diverso: Do-Mi-Sol, Mi-Sol-Do, Sol-Do-Mi sono sempre Do maggiore. Si chiamano rivolti.|Usando i rivolti la mano si sposta pochissimo: da Do (Do-Mi-Sol) puoi andare a Fa come Do-Fa-La e a Sol come Si-Re-Sol.|Il suono diventa più morbido e legato: è così che suonano i pianisti.','Suona Do maggiore nei tre rivolti, salendo e scendendo.|Suona Do (Do-Mi-Sol) → Fa (Do-Fa-La) → Sol (Si-Re-Sol) → Do.|Aggiungi la mano sinistra con le fondamentali.','So suonare i tre rivolti di Do|Nel giro la mano si sposta pochissimo|Suono il giro con le due mani',15,60,NULL,'p-triads',NULL,NULL,NULL,NULL),
('pz-6','pianoforte-da-zero',6,'Il primo brano a due mani','Accompagnare un brano famoso dall''inizio alla fine.','Let It Be dei Beatles usa proprio il giro che conosci: Do - Sol - La minore - Fa.|Usa i rivolti per suonare gli accordi legati e la mano sinistra per le fondamentali.|Quando riesci a suonarlo tutto, hai finito il corso: ora puoi accompagnare tante altre canzoni con gli stessi accordi.','Ripassa il giro Do - Sol - Am - Fa con le due mani.|Apri lo spartito dalla pagina del brano e segui la struttura.|Suona tutto il brano, cantando o ascoltando il disco.','Conosco gli accordi del brano|Suono senza fermarmi nei cambi|Suono tutto il brano',25,NULL,NULL,NULL,'let-it-be',NULL,NULL,NULL),
('dz-1','batteria-da-zero',1,'Il set e le bacchette','Conoscere i pezzi della batteria e impugnare bene le bacchette.','I pezzi principali sono la cassa (pedale destro), il rullante davanti a te, il charleston (hi-hat, pedale sinistro), i tom e i piatti crash e ride.|Regola lo sgabello in modo che le cosce siano più o meno parallele al pavimento, con il rullante all''altezza della pancia.|Tieni la bacchetta a un terzo dalla fine, tra pollice e indice; le altre dita la accompagnano senza stringere. Deve poter rimbalzare.','Siediti e regola sgabello e rullante.|Colpisci il rullante con una mano e lascia rimbalzare la bacchetta.|Suona la cassa a tempo con il metronomo, tenendo il tallone alzato o appoggiato come ti viene più comodo.','So il nome di ogni pezzo del set|La bacchetta rimbalza da sola|La cassa va a tempo con il metronomo',10,60,NULL,NULL,NULL,NULL,NULL,NULL),
('dz-2','batteria-da-zero',2,'Colpi singoli e doppi','Controllare le bacchette con entrambe le mani.','I rudimenti sono gli esercizi base della batteria. I più importanti sono il colpo singolo (D S D S) e il doppio (D D S S).|La mano debole deve suonare come quella forte: guarda che le bacchette partano dalla stessa altezza.','Colpi singoli in ottavi per un minuto.|Colpi doppi per un minuto, lasciando rimbalzare il secondo colpo.|Alterna una battuta di singoli e una di doppi.','Le due mani suonano con lo stesso volume|Il secondo colpo del doppio si sente bene|Cambio rudimento senza perdere il tempo',10,60,NULL,'d-rudiment',NULL,NULL,NULL,NULL),
('dz-3','batteria-da-zero',3,'Il primo brano: cassa, cassa, rullante','Suonare a tempo un ritmo famoso usando mani e piedi.','We Will Rock You è il ritmo più semplice e famoso del rock: due colpi di cassa e un colpo di rullante, poi una pausa.|È perfetto per coordinare piede e mano, e per imparare a contare le pause.','Suona cassa sui battiti 1 e 2, rullante sul 3, pausa sul 4.|Ripetilo con il metronomo finché non va da solo.|Suonalo insieme al disco.','Il ritmo va a tempo|La pausa ha la stessa durata degli altri battiti|Lo suono con il disco',10,80,'Battito:   1   2   3   4
Rullante:  .   .   o   .
Cassa:     o   o   .   .',NULL,'we-will-rock-you',NULL,NULL,NULL),
('dz-4','batteria-da-zero',4,'Il groove rock','Suonare il ritmo base di migliaia di brani rock e pop.','Il groove rock ha tre parti: charleston in ottavi con la mano destra, rullante sui battiti 2 e 4, cassa sull''1 e sul 3.|Impara prima mani e piedi separati, poi uniscili un pezzo alla volta.|Tieni il charleston chiuso con il piede sinistro: il suono è più corto e preciso.','Solo charleston in ottavi.|Aggiungi il rullante su 2 e 4.|Aggiungi la cassa su 1 e 3 e suona per due minuti.','Gli ottavi del charleston sono regolari|Rullante e cassa cadono con il charleston|Tengo il groove per due minuti',15,70,'Conta:  1  e  2  e  3  e  4  e
HH:     x  x  x  x  x  x  x  x
Rull.:  .  .  o  .  .  .  o  .
Cassa:  o  .  .  .  o  .  .  .','d-rock',NULL,NULL,NULL,NULL),
('dz-5','batteria-da-zero',5,'Il primo fill','Riempire una battuta e tornare al groove senza perdere il tempo.','Il fill è una piccola variazione che chiude una frase, di solito alla fine di 4 battute. Il più semplice sono quattro colpi per tom sui quattro battiti.|La cosa più importante non è il fill, è rientrare: sull''1 dopo il fill suona crash e cassa insieme.','Suona 3 battute di groove rock e 1 battuta di fill.|Rientra con crash e cassa sull''1.|Ripeti finché il rientro è sempre a tempo.','Il fill dura esattamente una battuta|Rientro con crash e cassa insieme|Non rallento durante il fill',15,70,NULL,'d-fill',NULL,NULL,NULL,NULL),
('dz-6','batteria-da-zero',6,'Un brano vero con il groove','Suonare il groove rock su un brano completo.','Billie Jean di Michael Jackson si regge su un groove molto simile a quello che hai imparato: charleston in ottavi, rullante su 2 e 4, cassa su 1 e 3.|Il segreto è la regolarità: lo stesso groove per tutto il brano, precisissimo.|Quando lo suoni tutto senza fermarti hai finito il corso!','Ripassa il groove rock a 90 BPM.|Ascolta il brano e conta le battute di ogni parte.|Suona tutto il brano insieme al disco.','Il groove resta uguale per tutto il brano|So quando arrivano le parti nuove|Suono tutto il brano con il disco',20,NULL,NULL,NULL,'billie-jean-drums',NULL,NULL,NULL)
